Расскажу подробнее о каждом слое.
Port: интерфейс контракта.
Port определяет, что мы делаем, но при этом не описывает как. В нашей реализации это интерфейс, который возвращает типизированный результат Result<T, E>. Вместо использования void или сырых Exception мы заставляем тест явно обрабатывать оба сценария: успех и бизнес-ошибку.
public interface CountryInfoServicePort {
 /**
 * Получение информации о стране для клиента
 * @param clientId идентификатор клиента
 * @param language язык ответа
 * @return результат с информацией о стране или ошибкой
 */
 Result<CountryInfo, ApiError> getCountryInfo(String clientId, Language language);
}
Result: обработка ошибок без исключений.
Вместо пробрасывания RestAssuredException мы используем иммутабельный контейнер Result. Это помогает исключить неявные падения и заставляет тест явно проверять оба сценария.
/**
 * Универсальный контейнер для результата выполнения операции.
 * Может содержать либо успешный результат, либо ошибку.
 *
 * @param <T> тип успешного результата
 * @param <E> тип ошибки
 */
@Value
 public class Result<T, E> {
 T value;
 E error;
 boolean isSuccess;
 public static <T, E> Result<T, E> success(T value) {
 return new Result<>(value, null, true);
 }
 public static <T, E> Result<T, E> failure(E error) {
 return new Result<>(null, error, false);
 }
 public boolean isSuccess() { return isSuccess; }
 public boolean isError() { return !isSuccess; }
 public Optional<T> getValue() { return Optional.ofNullable(value); }
 public Optional<E> getError() { return Optional.ofNullable(error); }
 public <R> Result<R, E> map(Function<T, R> mapper) {
 return isSuccess() ? Result.success(mapper.apply(value)) : Result.failure(error);
 }
 public <R> Result<R, E> flatMap(Function<T, Result<R, E>> mapper) {
 return isSuccess() ? mapper.apply(value) : Result.failure(error);
 }
 }
ApiError: типизированная ошибка API.
ApiError инкапсулирует парсинг ответа об ошибке. Если формат ответа изменится, правка вносится только в метод fromResponse() — тесты останутся неизменными.
@Value
 public class ApiError {
 int httpStatus;
 String errorCode;
 String errorMessage;
 public static ApiError fromResponse(Response response) {
 int statusCode = response.getStatusCode();
 String errorCode = response.jsonPath().getString("code");
 String errorMessage = response.jsonPath().getString("message");
 return new ApiError(
 statusCode,
 errorCode != null ? errorCode : "UNKNOWN_ERROR",
 errorMessage != null ? errorMessage : "Неизвестная ошибка"
 );
 }
 public static ApiError of(int httpStatus, String errorCode, String errorMessage) {
 return new ApiError(httpStatus, errorCode, errorMessage);
 }
 public static ApiError fromErrorCode(BusinessErrorCode errorCode, Object... args) {
 return new ApiError(
 errorCode.getHttpStatus(),
 errorCode.getErrorCode(),
 errorCode.formatErrorMessage(args)
 );
 }
 }
Adapter: реализация вызова.
Адаптер связывает Port с HTTP-слоем. Он обрабатывает статус-коды, парсит ошибки через ApiError.fromResponse() и маппит успешные ответы в доменные модели. Так позитивные и негативные кейсы возвращают один тип Result<T, ApiError>.
@Slf4j
 @RequiredArgsConstructor
 public class RestCountryInfoServiceAdapter implements CountryInfoServicePort {
 private final CountryInfoRequest clientCountryInfoRequest;
 @Override
 public Result<CountryInfo, ApiError> getCountryInfo(String clientId, Lang lang) {
 Response response = clientCountryInfoRequest.getCountryInfoResponse(clientId, lang);
 int statusCode = response.getStatusCode();

 if (sresponse.getStatusCode() == 200) {
 CountryInfoResponseDTO dto = response.as(CountryInfoResponseDTO.class);
return Result.success(CountryInfoMapper.toDomain(dto));
 }

 // Негативный кейс: делегируем парсинг ошибки в ApiError
 ApiError apiError = ApiError.fromResponse(response);
 log.warn("API error: status={}, code={}, message={}",
 apiError.getHttpStatus(), apiError.getErrorCode(), apiError.getErrorMessage());

 return Result.failure(apiError);
 }
 }
Domain Model и маппер.
Классы моделируют бизнес-сущности. Мы постарались уйти от использования Map и сырого JSON. Маппер отвечает за преобразование вложенных DTO в плоские или агрегированные доменные модели.
@Value @Builder
 public class CountryInfo {
 String infoText;
 List<Country> countries;
 }
 @Value
 public class Country {
 String codeAlpha2;
 String codeAlpha3;
 String codeNumeric;
 String name;
 }
 public class CountryInfoMapper {
 public static CountryInfo toDomain(CountryInfoResponseDTO dto) {
 return CountryInfo.builder()
 .infoText(dto.getInfo().getText())
 .countries(dto.getResultList().stream()
 .map(countryDTO -> new Country(
 countryDTO.getCountryCodeAlpha2(),
 countryDTO.getCountryCodeAlpha3(),
 countryDTO.getCountryCodeNumeric(),
 countryDTO.getCountryName()
 ))
 .collect(Collectors.toList()))
 .build();
 }
 }
Request: HTTP-слой.
Класс отвечает за формирование и отправку запроса через RestAssured. Пути и заголовки вынесены в конфигурацию. Путь эндпоинта и базовый URL хранятся в application-test.properties. Коды указаны явно для наглядности.
@RequiredArgsConstructor
 public class CountryInfoRequest {
 private final RequestSpecification requestSpecification;

 @Step("Выполнение запроса получения информации о стране для клиента {clientId}")
 public Response execute(String clientId, Language language) {
 return given()
 .spec(requestSpecification)
 .header("clientId", clientId)
 .header("x-lang", language.getCode())
 .log().all()
 .when()
 .get("/api/v1/country-info")
 .then()
 .log().all()
 .extract()
 .response();
 }
 }
Use Case: оркестратор бизнес-сценария.
Use Case вызывает Port и возвращает результат.
@Slf4j
 @RequiredArgsConstructor
 public class GetCountryInfoUseCase {
 private final CountryInfoServicePort countryInfoService;
 public Result<CountryInfo, ApiError> execute(String clientId, Language language) {
 log.info("🚀 Начало получения информации о стране для клиента: {}", clientId);

 // Прямой вызов порта без валидации входных данных
 Result<CountryInfo, ApiError> result = countryInfoService.getCountryInfo(clientId, language);

 // Логирование результата для отладки в CI
 if (result.isSuccess()) {
 log.debug("✅ Успешный ответ для clientId: {}", clientId);
 } else {
 log.warn("⚠️ API error for clientId={}: status={}, code={}",
 clientId,
 result.getError().map(ApiError::getHttpStatus).orElse(0),
 result.getError().map(ApiError::getErrorCode).orElse("UNKNOWN"));
 }

 return result;
 }
 }
Примеры тестов.
Задача фреймворка — отправить запрос и вернуть ответ. Решение о том, корректен ли ответ, принимает тест через ассерты.
// Позитивный кейс
 @Test
 void shouldReturnCountryInfoForValidClient() {
 String clientId = TestDataGenerator.generateClientId();

 Result<CountryInfo, ApiError> result = useCase.execute(clientId, Language.RU);

 assertThat(result.isSuccess()).isTrue();
 CountryInfo info = result.getValue().orElseThrow();
 assertThat(info.getCountries()).isNotEmpty();
 }
 // Негативный кейс: невалидный формат clientId
 @Test
 void shouldReturnBadRequestForInvalidClientId() {
 Result<CountryInfo, ApiError> result = useCase.execute("INVALID_FORMAT", Language.RU);

 assertThat(result.isError()).isTrue();

 ApiError error = result.getError().orElseThrow();
 assertThat(error.getHttpStatus()).isEqualTo(400);
 assertThat(error.getErrorCode()).isEqualTo("INVALID_CLIENT_ID_FORMAT");
 }
В реальной реализации все ожидаемые коды и сообщения ошибок вынесены в отдельный enum BusinessErrorCode. В ассертах сравнение происходит через BusinessErrorCode.INVALID_CLIENT)ID_FORMAT.getCode(). В примерах строки указаны хардкодом для наглядности и упрощения чтения кода.
Сборка зависимостей.
Для инициализации слоев мы используем SpringTest. Конфигурация вынесена в отдельный класс — это исключает дублирование new Adapter(new Request(...)) в каждом тесте. Spring здесь выступает как DI-контейнер и менеджер конфигурации.
@Configuration
 public class FrameworkConfig {
 @Bean
 public CountryInfoRequest countryInfoRequest(RequestSpecification spec) {
 return new CountryInfoRequest(spec);
 }
 @Bean
 public CountryInfoServicePort countryInfoPort(CountryInfoRequest request) {
 return new RestCountryInfoServiceAdapter(request);
 }
 @Bean
 public GetCountryInfoUseCase getCountryInfoUseCase(CountryInfoServicePort port) {
 return new GetCountryInfoUseCase(port);
 }
 }
Компромиссы и процесс разработки
Внедрение новой архитектуры меняет рабочий процесс. Издержки смещены на этап проектирования нового эндпоинта, но компенсируются скоростью последующей разработки и изоляцией изменений.
На какие компромиссы идем
Чем компенсируем
Создание первого эндпоинта требует описания полного набора слоев (Port, Adapter, Request, DTO, UseCase). На старте это требует больше времени, чем при добавлении одного метода в существующий монолитный класс (Steps).
Но после настройки структуры последующие эндпоинты добавляются по готовому шаблону: QA-инженер копирует пакет, заменяет контекст и адаптирует маппинг. Так время разработки сокращается.
Устранение зависимости от общего репозитория. Именно эта цель подтолкнула нас к поискам нового подхода для автоматизации регресса.
Копирование спецификации новой ручки из микросервиса в общий репозиторий со спецификациями → проверка конфликтов → коммит и ожидание аппрува → мерж в общий репозиторий → обновление версии зависимости в репозитории регресса → написание метода в Steps → сам тест.
Такая цепочка создавала риски и издержки. А еще способствовала накоплению технического долга.
рхитектура значительно увеличивает количество классов. Вместо одного Steps, содержащего все методы, появляется структурированный пакет слоев. Это требует от инженера понимания принципов контрактов и DI, но задает четкую границу ответственности. Изменения в одном слое не затрагивают остальные.
Изоляция в одном репозитории. Перенеся логику работы с API внутрь репозитория автотестов, мы больше не синхронизируем YAML между репозиториями и не обновляем внешние зависимости при изменении спецификации. Такой подход обеспечивает независимость от смежных команд и снижение рисков.
Мы сравнили подход прямой зависимости от спецификации с изолированными абстракциями по пяти критериям.
Точка отказа.
В подходе с зависимостью от спецификации изменение спецификации в чужом коммите вело к падению регресса без нашего участия. С изолированными абстракциями спецификация инкапсулирована в Request и Adapter. Тесты не зависят от путей, заголовков и структуры ответа.
Скорость написания теста.
Эта метрика отражает наш опыт. Цифры могут варьироваться в зависимости от зрелости инфраструктуры команды. Когда автоматизация регресса зависит от спецификации, алгоритм выглядит так:
Найти и обновить YAML в общем репозитории.
Создать MR, дождаться ревью и мержа.
Обновить версию зависимости в нашем проекте.
Перезапустить регресс.
Итого написание 5—7 тестов для нового эндпоинта на нашем проекте занимало от 4 до 8 часов, корректировка тестов для уже существующего — от 1 до 3. Большую часть времени занимали перенос и редактирование спецификации эндпоинта в общем репозитории, отладка и обновление зависимостей в репозитории регресса.
Когда мы перешли на изолированные абстракции, стали работать по такой схеме: готовый сценарий + генерация данных. В итоге правка уже существующего или написание набора новых тестов занимает ~10 минут или от 40 минут до ~1 часа соответственно.
Читаемость.
В нашем контексте тесты стали восприниматься как документация, но эффект может варьироваться в зависимости от опыта команды и стандартов код-ревью. Раньше: YamlClient.execute(“api.endpoint.getCountryInfo”) — магия без контекста. Теперь: useCase.execute(clientId, Language.RU) — бизнес-язык без деталей реализации.
Онбординг QA.
В нашей команде адаптация сократилась с 2—3 недель до 3—5 дней. Результаты зависят от начального уровня специалиста и наличия документации.
Мы ушли от истории, когда нужно разбираться в структуре общего репозитория и правилах работы с YAML. Сейчас тест понятен за 5 минут — спецификация скрыта за абстракциями.
Стоимость поддержки.
Когда автоматизация регресса зависела от спецификации, каждое падение влекло за собой часы расследований и координацию с другими командами. Теперь в новой изолированной истории мы можем пофиксить и локализовать проблему в одном слое.
Результаты вместо заключения
После всех изменений у нас появилась стабильность без зависимости от других команд. Ни одного падения регресса из-за изменений в общем репозитории спецификаций не случилось.
Выросла скорость разработки. Время написания типового теста сократилось в ~5 раз. Не нужно ждать мержа в общем репозитории: готовый сценарий + генерация данных — и тест готов за минуты.
Мы разработали три фреймворка, основываясь на описанной архитектуре. А еще мигрировали один, реализованный согласно старому подходу, затратив на это примерно 8 рабочих дней.
Адаптация коллег к автоматизации сократилась с недель до дней. Инциденты, которые раньше требовали часов расследования и координации с другими командами, теперь решаются за минуты: проблема локализована в одном слое. Автоматизация регресса перестала быть головной болью всей команды и стала приносить удовольствие. Тесты пишутся легко, читаются как документация, падения больше не вызывают панику. Технический долг перестал расти, фичи все чаще покрываются регрессом прямо во время тестирования, автоматизация практически не откладывается в долгий ящик.
Отказ от хардкода в пользу генератора на базе Builder облегчил работу QA с тестовыми данными. Тест вызывает метод генератора, который автоматически подставляет валидные значения для всех обязательных полей. В самом тесте при автоматизации указываются только те параметры, которые влияют на логику сценария. Например, передается невалидное значение параметра для проверки негативных сценариев.
В итоге мы получили:
Соблюдение DRY. Логика подготовки тестовых данных вынесена в отдельный класс, исчезли десятки строк кода с подготовкой тестовых данных. Если меняется контракт, правка вносится только в одном месте.
Гарантированную уникальность. Для каждого вызова генерируется полностью новый набор данных — это устранило конфликты и flaky-тесты, которые были завязаны на одно и то же значение.
Мы начали внедрение нового подхода до критического инцидента с падением регресса. В результате получили стабильный регресс и контролируемый процесс разработки тестов. Не беремся утверждать, что наш подход — истина в последней инстанции. Мы придерживаемся мнения, что контекст решает: в небольших проектах такая структура может казаться избыточной. Мы продолжаем развивать наши фреймворки и искать способы их улучшения, не останавливаясь на достигнутом.
А как вы изолируете тесты от внешних зависимостей и сталкивались ли вы с такой проблемой на своем опыте? Делитесь подходами в комментариях — обсудим.
P. S. Все примеры кода в статье сгенерированы с помощью ИИ на основе реальных архитектурных решений нашей команды. Мы сознательно изменили имена классов, структуру пакетов и детали реализации, чтобы сохранить конфиденциальность внутренних систем и избежать раскрытия приватных данных. Суть архитектурных решений, принципы и результаты переданы точно.

Вступление
В недавней статье
«Частотомер с БИХ‑фильтром НЧ в 1 Кбайте на ATtiny13»
я рассказывал, как удалось уместить цифровую фильтрацию синусоиды, динамическую индикацию и работу с датчиком DS18B20 на единственном 8-битном таймере. В симуляторе SimulIDE всё работало как часы. Но когда я прошил реальный чип и собрал схему в «железе», датчик температуры наотрез отказался отвечать.
Симптом: 7 бит вместо 8
На первый взгляд всё выглядело странно. Импульс сброса Reset (около 640 мкс) проходил нормально, и датчик исправно отвечал импульсом присутствия Presence. Но дальше начиналась мистика: при передаче любой команды (0xCC, 0x44 или 0xBE) на шине 1-Wire появлялось ровно
7 бит вместо 8
. Причем стабильно пропадал самый первый (младший) бит каждого байта, независимо от того, шел за ним 0 или 1:
· Вместо 0xCC (00110011) уходило 0110011.
· Вместо 0xBE (01111101) уходило 1111101.
Инструмент: логический анализатор на RP2040 за 15 минут
Обычный осциллограф здесь помогал плохо: такты таймера идут каждые ~213 мкс, внутри такта импульсы длительностью от 2 до 78 мкс, при этом автомат 1-Wire пропускает «нагруженные» такты перехода синусоиды через ноль (паузы до 19–20 мс), да еще и частота внутреннего RC-генератора плавает от температуры.
Под рукой оказалась плата на
RP2040
, из которой за вечер получился специализированный сниффер под эту задачу.
(Примечание: не забываем, что у RP2040 логика 3.3 В без толерантности к 5 В, поэтому сигналы с ATtiny13 заводим через резистивные делители).
const int pin_IR = D4;
#define MAX_SIGNALS 100 // Максимум 100 изменений сигнала в посылке

// Variables updated inside an ISR must be marked as volatile
volatile bool pinStateChanged = false;
volatile int latestPinState = LOW;

volatile unsigned long timestamps[MAX_SIGNALS];
volatile int signal_count = 0;
volatile unsigned long last_time = 0;
volatile bool data_ready = false;
volatile int old_data = HIGH;

void pinISR() {
//void IRAM_ATTR handlePinChange() {
 int new_data = digitalRead(pin_IR);
 new_data += digitalRead(pin_IR);
 new_data += digitalRead(pin_IR);
 new_data += digitalRead(pin_IR);
 new_data += digitalRead(pin_IR);
 new_data += digitalRead(pin_IR);
// new_data += digitalRead(pin_IR);
// new_data += digitalRead(pin_IR);
 if (new_data < 3) {new_data=LOW;} else {new_data=HIGH;}
 if (old_data != new_data) {
 old_data = new_data;
 unsigned long now = micros();

 if (data_ready) return; // Если старая посылка еще не выведена, игнорируем новые

 if (signal_count < MAX_SIGNALS) {
 // Считаем длительность текущего состояния (высокого или низкого)
 timestamps[signal_count] = now - last_time;
 signal_count++;
 }

 last_time = now;
 }
}

void setup() {
 Serial.begin(115200);
 pinMode(pin_IR, INPUT);

 // Привязываем прерывание на ЛЮБОЕ изменение уровня (CHANGE)
 attachInterrupt(digitalPinToInterrupt(pin_IR), pinISR, CHANGE);
 last_time = micros();
}

void loop() {
 // Если прерывания прекратились более чем на 800 мс (800000 мкс) — посылка завершена
 if (signal_count > 0 && (micros() - last_time > 800000)) {
 detachInterrupt(digitalPinToInterrupt(pin_IR)); // Временно отключаем

// Serial.println("\n--- Новая посылка ---");
// Serial.print("Количество изменений: "); Serial.println(signal_count);
// Serial.println("Тайминги импульсов/пауз (в микросекундах):");
 Serial.println("==");

 // Выводим массив. Первое значение игнорируем (это время ожидания до нажатия)
 for (int k = 1; k < signal_count; k++) {
 Serial.print(timestamps[k]);
 if (k < signal_count - 1) Serial.print(", ");
 }
 Serial.println();

 // Сброс для следующего приема
 signal_count = 0;
 last_time = micros();

 attachInterrupt(digitalPinToInterrupt(pin_IR), pinISR, CHANGE);
 }
}
